function costoLabor23(c, x) { const fH = Math.min(1, n0(x.horas) / (n0(cfgCosecha().horasJornal) || 8)) || 1; const mo = c.base === 'Jornal' ? tarifaLab(c) * n0(x.personas) * fH : tarifaLab(c) * n0(x.cantidad); const al = c.incluyeAlim ? n0(cfgCosecha().alimentacion) * n0(x.personas) * fH : 0; return { mo, al, total: mo + al + n0(x.insumoCosto) }; }
