function leerLabor23() { const g = k => document.getElementById(k).value; const c = catLabores.find(x => x.id === g('lr-c')); return { c, x: { cantidad: n0(g('lr-q')), personas: Math.max(1, n0(g('lr-p'))), horas: n0(g('lr-h')), insumoCosto: n0(g('lr-ic')) } }; }
